entries[18499] = { ["name"] = "Berserkerwut", ["text"] = "Sofort 30 sek. Abklingzeit\nVersetzt Euch in eine Berserkerwut, die Euch immun gegenüber Furcht und Kopfnuss- sowie Handlungsunfähigkeitseffekten macht [ Glyphe 'Berserkerwut' : und Ihr erzeugt sofort 5 Wut ]. Des Weiteren erzeugt Ihr zusätzliche Wut, wenn Ihr Schaden erleidet. Hält 10 Sek. lang an." }
entries[18500] = { ["name"] = "Flügelstoß", ["text"] = "Wirken in 0.5 sek.\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden 28275 to 31725 Schaden zu und stößt sie zurück." }
entries[18501] = { ["name"] = "Wutanfall", ["text"] = "Sofort\nErhöht 5 Sek. lang den körperlichen Schaden, den der Zaubernde verursacht, und sein Angriffstempo." }
entries[18502] = { ["name"] = "Fluch von Hakkar", ["text"] = "200 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nEntzieht einem Feind alle 5 Sek. 100 Mana und überträgt sie 2 Min. lang auf den Zaubernden." }
entries[18503] = { ["name"] = "Verhexung", ["text"] = "20 Mana 20 Meter Reichweite\nSofort\nTransformiert einen Feind in ein Huhn, sodass er 5 Sek. lang weder angreifen noch Zauber wirken kann." }
entries[18530] = { ["name"] = "Göttlicher Furor", ["text"] = "Verringert die Zauberzeit Eurer Zauber 'Heilige Pein', 'Heiliges Feuer', 'Heilung' und 'Große Heilung' um 0,15 Sek." }
entries[18531] = { ["name"] = "Göttlicher Furor", ["text"] = "Verringert die Zauberzeit Eurer Zauber 'Heilige Pein', 'Heiliges Feuer', 'Heilung' und 'Große Heilung' um 0,35 Sek." }
entries[18533] = { ["name"] = "Göttlicher Furor", ["text"] = "Verringert die Zauberzeit Eurer Zauber 'Heilige Pein', 'Heiliges Feuer', 'Heilung' und 'Große Heilung' um 0.5 Sek." }
entries[18540] = { ["name"] = "Verdammniswache beschwören", ["text"] = "80% von Grundmana\nSofort 10 min Abklingzeit\nBeschwört eine Verdammniswache, die 45 Sek. lang an Eurer Seite kämpft.\n\nDie Verdammniswache wird Euch unterstützen, indem sie das Ziel angreift, welches vom Effekt Eurer Zauber 'Omen der Pein' oder 'Omen der Verdammnis' betroffen ist." }
entries[18542] = { ["name"] = "Feuerbrand", ["text"] = "(Procchance: 10%)" }
entries[18543] = { ["name"] = "Flammenpeitsche", ["text"] = "30 Meter Reichweite\nSofort\nVerbrennt sofort einen Feind und fügt ihm dann 15 Sek. lang alle 3 Sek. zusätzlichen Feuerschaden zu." }
entries[18545] = { ["name"] = "Skorpidgift", ["text"] = "10 Mana 5 - 30 Meter Reichweite\nBenötigt Distanzwaffe\nSticht einen Feind und verringert 20 Sek. lang Stärke und Beweglichkeit des Ziels um 1." }
entries[18546] = { ["name"] = "Overdrive", ["text"] = "Sofort\nMacht den Zaubernden bewegungsunfähig, erhöht aber 6 Sek. lang sein Angriffstempo um 100%." }
entries[18551] = { ["name"] = "Mentale Stärke", ["text"] = "Erhöht Eure gesamte Intelligenz um 3%." }
