entries[18560] = { ["name"] = "Mondstoff", ["text"] = "Wirken in 50 sek.\nReagenzien:\nTeufelsstoff (2)\nDie Läuterung und Verwandlung von besudeltem Teufelsstoff in Mondstoff kann nur an einem Mondbrunnen durchgeführt werden. Zudem werden es die Wasser nur hin und wieder gestatten, auf diese Weise benutzt zu werden." }
entries[18561] = { ["name"] = "Schießen", ["text"] = "5 - 30 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nSchießt auf den Feind und fügt körperlichen Schaden zu." }
entries[18562] = { ["name"] = "Rasche Heilung", ["text"] = "10% von Grundmana 40 Meter Reichweite\nSofort 15 sek. Abklingzeit\n[ Glyphe 'Rasche Heilung' : Heilt ein Ziel, auf dem ein Effekt von 'Verjüngung' oder 'Nachwachsen' wirkt, sofort um 0 / Zehrt einen auf das Ziel wirkenden Effekt von 'Verjüngung' oder 'Nachwachsen' auf, um es sofort um 0 zu heilen.]" }
