entries[19493] = { ["name"] = "Verbessertes Skorpidgift", ["text"] = "Verringert die Ausdauer von Zielen, die von Eurer Fähigkeit 'Skorpidgift' betroffen sind, in Höhe von 20% der verringerten Stärke." }
