entries[19496] = { ["name"] = "Magmafesseln", ["text"] = "Sofort\nVerringert das Bewegungstempo von in der Nähe befindlichen Feinden 15 Sek. lang um 60%." }
entries[19497] = { ["name"] = "Ausbruch", ["text"] = "Sofort\nFügt allen Gegnern in der Nähe 1850 to 2150 Feuerschaden zu und stößt sie zurück." }
entries[19501] = { ["name"] = "Spiralwelle des Todes" }
entries[19502] = { ["name"] = "Kränkliches Tier-Aura" }
entries[19503] = { ["name"] = "Streuschuss", ["text"] = "20 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBenötigt Distanzwaffe\nEin einzelner Kurzdistanzschuss, der 50% Waffenschaden zufügt und das Ziel 4 Sek. lang die Orientierung verlieren lässt. Jeglicher erlittene Schaden wird den Effekt aufheben. Stoppt Euren Angriff bei Benutzung." }
entries[19505] = { ["name"] = "Magie verschlingen", ["text"] = "5% von Grundmana 30 Meter Reichweite\nSofort 15 sek. Abklingzeit\nReinigt 1 nützlichen Magieeffekt von einem Feind. Wird ein Effekt verschlungen, [ Glyphe 'Teufelsjäger' : werden sowohl der Teufelsjäger als auch der Hexenmeister / wird der Teufelsjäger] um [ 1501 + ((Spell power * 0.5) * 0.3)] geheilt." }
entries[19506] = { ["name"] = "Aura des Volltreffers", ["text"] = "Erhöht die Angriffskraft aller Gruppen- und Schlachtzugsmitglieder im Umkreis von 100 Metern um 20% sowie ihre Distanzangriffskraft um 10%." }
entries[19512] = { ["name"] = "Salbe auftragen", ["text"] = "5 Meter Reichweite\nWirken in 1.3 sek.\nTools: Heilende Tiersalbe\nHeilt ein kränkliches Tier, das mit der Besudelung durch eine Vergiftung infiziert ist." }
entries[19513] = { ["name"] = "Blitzschlagwolke", ["text"] = "30 Meter Reichweite\nSofort 40 sek. Abklingzeit\nLässt eine Blitzschlagwolke entstehen, die 15 Sek. anhält und allen Feinden im ausgewählten Gebiet 28 to 32 Naturschaden und alle 5 Sek. 42 to 48 zusätzlichen Schaden zufügt." }
entries[19514] = { ["name"] = "Blitzschlagschild", ["text"] = "30 Meter Reichweite\nSofort 10 sek. Abklingzeit\nUmgibt den Zaubernden mit 3 Kugelblitzen, die eine Chance von 50% gewähren, Nahkampf- oder Distanzangreifern Naturschaden zuzufügen. Jedes Mal, wenn der Blitzschlagschild ausgelöst wird, wird ein Kugelblitz aufgezehrt. Der Schild endet nach Ablauf von 10 Min. oder nachdem er 3-mal ausgelöst wurde.\n(Procchance: 50%, 3.5s Abklingzeit)" }
entries[19516] = { ["name"] = "Raserei", ["text"] = "Sofort\nErhöht das Angriffstempo des Zaubernden." }
entries[19548] = { ["name"] = "Eisklauenbären zähmen", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 20 sek.)\nBeginnt mit der Zähmung eines Eisklauenbären, damit er 15 Minuten lang Euer Gefährte wird. Falls Ihr die Aufmerksamkeit des Wildtiers aus irgendeinem Grund verlieren solltet, schlägt der Vorgang der Zähmung fehl." }
entries[19557] = { ["name"] = "Verbesserte Augen des Wildtiers", ["text"] = "Erhöht die Dauer Eurer Fähigkeit 'Augen des Wildtiers' um 30 Sek." }
entries[19558] = { ["name"] = "Verbesserte Augen des Wildtiers", ["text"] = "Erhöht die Dauer Eurer Fähigkeit 'Augen des Wildtiers' um 60 Sek." }
entries[19559] = { ["name"] = "Orientierung", ["text"] = "Erhöht den Tempo-Bonus Eures 'Aspekt des Geparden' und 'Aspekt des Rudels' um 4% und erhöht Eure Reitgeschwindigkeit um 5%. Die Erhöhung der Reitgeschwindigkeit ist nicht mit anderen Effekten stapelbar." }
entries[19560] = { ["name"] = "Orientierung", ["text"] = "Erhöht den Tempo-Bonus Eures 'Aspekt des Geparden' und 'Aspekt des Rudels' um 8% und erhöht Eure Reitgeschwindigkeit um 10%. Die Erhöhung der Reitgeschwindigkeit ist nicht mit anderen Effekten stapelbar." }
