entries[19564] = { ["name"] = "Wasserprobe einholen", ["text"] = "5 Meter Reichweite\nWirken in 3 sek.\nHolt eine Wasserprobe vom Wasserfall am Eingang der Höhle der Klippenquellfälle." }
