entries[19566] = { ["name"] = "Salzstreuer", ["text"] = "Wirken in 2 sek.\nReagenzien:\nTiefsteinsalz\nSiebt und mahlt Tiefsteinsalz zu raffiniertem Tiefsteinsalz." }
entries[19567] = { ["name"] = "Salzstreuer", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer\nReagenzien:\nMithrilgehäuse , Thoriumbarren (6), Goldkraftkern (3)\nBenötigt Lederverarbeitung\n(250)\nBenutzen: Siebt und mahlt Tiefsteinsalz zu raffiniertem Tiefsteinsalz." }
