entries[19574] = { ["name"] = "Zorn des Wildtiers", ["text"] = "100 Meter Reichweite\nSofort 2 min Abklingzeit\nVersetzt Euer Tier in einen Kampfrausch, wodurch es 10 Sek. lang 20% zusätzlichen Schaden verursacht. Einmal im Kampfrausch, gibt es keine Möglichkeit mehr, Euer Tier zu stoppen, es sei denn, es wird getötet." }
entries[19577] = { ["name"] = "Einschüchterung", ["text"] = "100 Meter Reichweite\nSofort 1 min Abklingzeit\nBefiehlt Eurem Tier, sein Ziel einzuschüchtern. Verursacht ein hohes Maß an Bedrohung und betäubt das Ziel 3 Sek. lang. Hält 15 Sek. lang an." }
