entries[19666] = { ["name"] = "Silberdietrich", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nSilberbarren , Rauer Schleifstein\nSilberdietrich\n(2)\nBenötigt Schmiedekunst\n(100)\nBenutzen: Ermöglicht das Öffnen von einfachen Schlössern bis zu einer Schlossknackenfertigkeit von 25. Dieser Vorgang verzehrt den Dietrich." }
