entries[19698] = { ["name"] = "Inferno", ["text"] = "Sofort\nKanalisiert die Flammen des Geschmolzenen Kerns, um allen Gegnern in der Nähe Feuerschaden zuzufügen. Der Schaden erhöht sich, je länger das Inferno kanalisiert wird." }
entries[19699] = { ["name"] = "Pirschenden Nachtsäbler zähmen", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 20 sek.)\nBeginnt mit der Zähmung eines pirschenden Nachtsäblers, damit er 15 Minuten lang Euer Gefährte wird. Falls Ihr die Aufmerksamkeit des Wildtiers aus irgendeinem Grund verlieren solltet, schlägt der Vorgang der Zähmung fehl." }
entries[19700] = { ["name"] = "Strigidkreischer zähmen", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 20 sek.)\nBeginnt mit der Zähmung eines Strigidkreischers, damit er 15 Minuten lang Euer Gefährte wird. Falls Ihr die Aufmerksamkeit des Wildtiers aus irgendeinem Grund verlieren solltet, schlägt der Vorgang der Zähmung fehl." }
entries[19701] = { ["name"] = "Brocken", ["text"] = "5 - 30 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Brocken auf einen Feind, stößt ihn zurück und fügt körperlichen Schaden zu." }
entries[19702] = { ["name"] = "Drohende Verdammnis", ["text"] = "Sofort\nFügt in der Nähe befindlichen Feinden nach 10 Sek. 2000 Schattenschaden zu." }
entries[19703] = { ["name"] = "Lucifrons Fluch", ["text"] = "Sofort\nVerflucht in der Nähe befindliche Feinde und erhöht die Kosten für ihre Zauber sowie ihre Fähigkeiten 5 Min. lang um 100%. Diese Kostenerhöhung gilt für alle Zauber und Fähigkeiten, unabhängig davon, ob sie Mana, Wut oder Energie kosten." }
entries[19704] = { ["name"] = "Erdelementar beschwören", ["text"] = "Sofort\nBeschwört 1 Erdelementar als Begleitung für den Zaubernden bis zur Freigabe." }
entries[19705] = { ["name"] = "Satt", ["text"] = "Sofort\nErhöht Ausdauer und Willenskraft um 2. Hält 15 Min. lang an." }
entries[19706] = { ["name"] = "Satt", ["text"] = "Sofort\nErhöht Ausdauer und Willenskraft um 4. Hält 15 Min. lang an." }
entries[19708] = { ["name"] = "Satt", ["text"] = "Sofort\nErhöht Ausdauer und Willenskraft um 6. Hält 15 Min. lang an." }
entries[19709] = { ["name"] = "Satt", ["text"] = "Sofort\nErhöht Ausdauer und Willenskraft um 8. Hält 15 Min. lang an." }
entries[19710] = { ["name"] = "Satt", ["text"] = "Sofort\nErhöht Ausdauer und Willenskraft um 12. Hält 15 Min. lang an." }
entries[19711] = { ["name"] = "Satt", ["text"] = "Sofort\nErhöht Ausdauer und Willenskraft um 14. Hält 15 Min. lang an." }
entries[19712] = { ["name"] = "Arkane Explosion", ["text"] = "Wirken in 0.5 sek.\nLässt eine Druckwelle aus Magie entstehen und fügt in der Nähe befindlichen Feinden 925 to 1075 Arkanschaden zu." }
entries[19713] = { ["name"] = "Shazzrahs Fluch", ["text"] = "Sofort\nErhöht den erlittenen Magieschaden von in der Nähe befindlichen Feinden 5 Min. lang um 100%." }
entries[19714] = { ["name"] = "Magische Erdung", ["text"] = "250 Mana\nSofort\nVerringert den vom Zaubernden erlittenen Magieschaden 30 Sek. lang um 50%." }
entries[19715] = { ["name"] = "Gegenzauber", ["text"] = "30 Meter Reichweite\nSofort\nKontert das Zauberwirken von in der Nähe befindlichen Feinden und verhindert 10 Sek. lang, dass ein Zauber dieser Art der Magie gewirkt werden kann. Führt zu einem hohen Maß an Bedrohung." }
entries[19716] = { ["name"] = "Gehennas' Fluch", ["text"] = "Sofort\nVerringert 5 Min. lang die Heileffekte von in der Nähe befindlichen Feinden um 75%." }
entries[19717] = { ["name"] = "Feuerregen", ["text"] = "40 Meter Reichweite\nSofort\nLässt einen Schmelzregen niedergehen, der alle Feinde in einem ausgewählten Gebiet verbrennt und ihnen 6 Sek. lang alle 2 Sek. 925 to 1075 Feuerschaden zufügt." }
entries[19719] = { ["name"] = "Schmuckstück benutzen", ["text"] = "5 Meter Reichweite\nWirken in 3 sek.\nVollendet die Wasserzeitprüfung am Schrein von Remulos." }
entries[19720] = { ["name"] = "Anhänger kombinieren", ["text"] = "5 Meter Reichweite\nWirken in 3 sek.\nReagenzien:\nHalber Anhänger der Wasserbelastbarkeit\nMit dem halben Anhänger der Wasserbelastbarkeit kombinieren, um den Anhänger des Seelöwen zu formen." }
entries[19721] = { ["name"] = "Gardist wiederauferstehen lassen" }
entries[19722] = { ["name"] = "Scharlachroten Reitersoldaten beschwören" }
entries[19723] = { ["name"] = "Hochentwickelte Zielattrappe - Ereignis 003", ["text"] = "10 Meter Reichweite\nSofort\nLässt eine Zielattrappe auf den Boden fallen, die in der Nähe befindliche Monster dazu bringt, sie anzugreifen. Hält 3 Minuten lang an." }
entries[19725] = { ["name"] = "Untote vertreiben", ["text"] = "75 Mana 20 Meter Reichweite\nWirken in 1.5 sek.\nZwingt einen untoten Feind bis zu 20 Sek. lang zu fliehen. Es kann immer nur jeweils ein Ziel zur Flucht gezwungen werden." }
entries[19726] = { ["name"] = "Aura des Widerstands", ["text"] = "Sofort\nErhöht den Widerstand von in der Nähe befindlichen Gruppenmitgliedern gegen alle Arten von Magie bis Abbruch lang um 1." }
entries[19727] = { ["name"] = "Wassergestank" }
entries[19728] = { ["name"] = "Schattenblitz", ["text"] = "40 Meter Reichweite\nWirken in 0.5 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Feind und verursacht 2250 to 2750 Schattenschaden." }
entries[19729] = { ["name"] = "Schattenblitz", ["text"] = "40 Meter Reichweite\nWirken in 0.5 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Feind und verursacht 2250 to 2750 Schattenschaden." }
entries[19730] = { ["name"] = "Stoß", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nSchlägt einen Feind und fügt normalen Schaden plus 25 zu." }
entries[19740] = { ["name"] = "Segen der Macht", ["text"] = "19% von Grundmana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen, welcher seine Angriffskraft um 20 %, seine Distanzangriffskraft um 10 % erhöht und alle 5 Sek. 1 Mana regeneriert. Hält 1 Stunde lang an. Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[19746] = { ["name"] = "Aura der Konzentration", ["text"] = "Sofort\nVerringert die erhöhte Zauberdauer oder verringerte Kanalisierungsdauer durch erlittenen Schaden von Gruppen- oder Schlachtzugsmitgliedern im Umkreis von 40 Metern um 35%. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[19749] = { ["name"] = "Gardistenping" }
entries[19750] = { ["name"] = "Lichtblitz", ["text"] = "31% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek.\nEine schnelle, teure Heilung, die ein befreundetes Ziel um 7024 heilt." }
entries[19755] = { ["name"] = "Schreckenskralle", ["text"] = "30 Meter Reichweite\nWirken in 1 sek.\nVerringert 1 Min. lang alle Attribute des Ziels um 10." }
entries[19767] = { ["name"] = "Aynashas Bogen", ["text"] = "30 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nSchießt auf den Feind und fügt körperlichen Schaden zu." }
entries[19769] = { ["name"] = "Thoriumgranate", ["text"] = "45 Meter Reichweite\nWirken in 1 sek." }
entries[19770] = { ["name"] = "Gizeltons Karawane" }
entries[19771] = { ["name"] = "Sägebiss", ["text"] = "10 Meter Reichweite\nSofort\nVerursacht 30 Sek. lang insgesamt 1500 körperlichen Schaden bei einem Feind." }
entries[19772] = { ["name"] = "Lebensechte Kröte", ["text"] = "Sofort\nMit Rechtsklick Eure lebensechte mechanische Kröte beschwören oder wieder freigeben." }
entries[19773] = { ["name"] = "Elementarfeuer", ["text"] = "100 Meter Reichweite\nWirken in 0.5 sek.\nVersengt die Seele Eures gebundenen Wesens und lässt es sein Leben aushauchen, um Euch zu stärken." }
entries[19774] = { ["name"] = "Ragnaros beschwören", ["text"] = "Wirken in 10 sek.\nAus seinem Schlummer unter dem Geschmolzenen Kern gerissen, wird Ragnaros, der Feuerlord, erweckt." }
entries[19775] = { ["name"] = "Dunkle Besserung", ["text"] = "500 Mana 60 Meter Reichweite\nWirken in 2 sek.\nHeilt bei einem Verbündeten 27750 to 32250 Schaden unter Verwendung von dunkler Magie." }
entries[19776] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "95 Mana 30 Meter Reichweite\nSofort\nMurmelt ein Wort der Dunkelheit, das einem Feind 15 Sek. lang alle 3 Sek. Schattenschaden zufügt." }
entries[19777] = { ["name"] = "Dunkler Stoß", ["text"] = "250 Mana 10 Meter Reichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nWeiht die Waffe des Zaubernden und verursacht bei ihrem nächsten Angriff 570 to 630 zusätzlichen Schaden. Der gesamte zugefügte Schaden wird als Schattenschaden angesehen." }
entries[19778] = { ["name"] = "Demoralisierender Ruf", ["text"] = "Sofort\nVerringert Nahkampf- und Distanzangriffskraft von in der Nähe befindlichen Feinden 30 Sek. lang um 300." }
entries[19779] = { ["name"] = "Inspirieren", ["text"] = "45 Meter Reichweite\nSofort\nErhöht den von einem Verbündeten zugefügten körperlichen Schaden um 25% und sein Angriffstempo 10 Sek. lang um 100%." }
entries[19780] = { ["name"] = "Hand von Ragnaros", ["text"] = "Sofort\nFügt in der Nähe befindlichen Feinden 300 to 400 Feuerschaden zu, stößt sie zurück und betäubt sie 2 Sek. lang." }
entries[19781] = { ["name"] = "Flammenspeer", ["text"] = "45 Meter Reichweite\nSofort\nWirft einen Flammenspeer, verursacht bei einem Feind 850 to 1150 Feuerschaden und versengt außerdem alle anderen Feinde in der Nähe des Ziels." }
entries[19784] = { ["name"] = "Dunkeleisenbombe", ["text"] = "15 Meter Reichweite\nWirken in 1 sek." }
entries[19785] = { ["name"] = "Werfen", ["text"] = "8 - 40 Meter Reichweite\nSofort\nWirft eine Waffe nach einem Feind und fügt 2125 to 2875 Schaden zu." }
entries[19786] = { ["name"] = "Stille widerstehen", ["text"] = "Erhöht Euren Widerstand gegen Stilleeffekte um 7%." }
entries[19787] = { ["name"] = "Rüstung erhöht 110", ["text"] = "+110 Rüstung." }
entries[19788] = { ["name"] = "Dichtes Sprengpulver", ["text"] = "Wirken in 3 sek.\nReagenzien:\nVerdichteter Stein (2)" }
entries[19790] = { ["name"] = "Thoriumgranate", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumapparat , Thoriumbarren (3), Dichtes Sprengpulver (3), Runenstoff (3)\n(3)\nBenötigt Ingenieurskunst\n(260)" }
entries[19791] = { ["name"] = "Thoriumapparat", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nThoriumbarren (3), Runenstoff" }
entries[19792] = { ["name"] = "Thoriumgewehr", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr (2), Mithrilgehäuse (2), Thoriumapparat (2), Thoriumbarren (4), Tödliches Zielfernrohr\nThoriumgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n70 - 131 Schaden Tempo 2.50\n(40.20 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\n47\nAnlegen: Erhöht die Distanzangriffskraft um 17." }
entries[19793] = { ["name"] = "Lebensechte mechanische Kröte", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEssenz des Lebens , Thoriumapparat (4), Goldkraftkern , Unverwüstliches Leder\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Eure lebensechte mechanische Kröte beschwören oder wieder freigeben." }
entries[19794] = { ["name"] = "Zaubermachtschutzbrille Xtrem-Plus", ["text"] = "Wirken in 45 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nZaubermachtschutzbrille Xtrem , Sternrubin (4), Verzaubertes Leder (2), Runenstoff (8)\nZaubermachtschutzbrille Xtrem-Plus\nWird beim Anlegen gebunden\nKopf Stoff\n111 Rüstung\n+23 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Ingenieurskunst\n(270)" }
entries[19795] = { ["name"] = "Thoriumröhre", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nThoriumbarren (6)" }
entries[19796] = { ["name"] = "Dunkeleisengewehr", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nThoriumröhre (2), Dunkeleisenbarren (6), Tödliches Zielfernrohr (2), Blauer Saphir (2), Großer Opal (2), Unverwüstliches Leder (4)\nDunkeleisengewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n89 - 167 Schaden Tempo 2.70\n(47.41 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\n50\nAnlegen: Gewährt eine Chance, Euer Distanzziel mit einem Schattenschuss zu treffen und 18 to 26 Schattenschaden zu verursachen." }
entries[19797] = { ["name"] = "Fackel der Vergeltung herbeizaubern" }
entries[19798] = { ["name"] = "Erdbeben", ["text"] = "Sofort\nVerursacht bei in der Nähe befindlichen Feinden 1388 to 1612 Schaden." }
entries[19799] = { ["name"] = "Dunkeleisenbombe", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumapparat (2), Dunkeleisenbarren , Dichtes Sprengpulver (3), Runenstoff (3)\n(3)\nBenötigt Ingenieurskunst\n(285)" }
entries[19801] = { ["name"] = "Einlullender Schuss", ["text"] = "20 Fokus 35 Meter Reichweite\nSpontanzauber\nBenötigt Distanzwaffe\nVersucht, 1 Wuteffekt und 1 Magieeffekt von einer feindlichen Kreatur zu entfernen." }
entries[19802] = { ["name"] = "Arkanitdrachling beschwören", ["text"] = "Sofort 1 Stunde Abklingzeit\nDer Arkanitdrachling wird zum Leben erweckt und verteidigt Euch 1 Min. lang." }
entries[19804] = { ["name"] = "Arkanitdrachling", ["text"] = "Sofort 5 min Abklingzeit\nAktiviert Euren Arkanitdrachling, damit er 1 Min. lang für Euch kämpft." }
entries[19805] = { ["name"] = "Meisterliche Zielattrappe", ["text"] = "10 Meter Reichweite\nSofort\nLässt eine Zielattrappe auf den Boden fallen, die in der Nähe befindliche Monster dazu bringt, sie anzugreifen. Die Attrappe bleibt bis zu ihrer Zerstörung aktiv, maximal jedoch für 15 Sekunden." }
