entries[19809] = { ["name"] = "Meisterliche Zielattrappe Passiv", ["text"] = "Bringt in der Nähe befindliche Monster dazu, den Zaubernden anzugreifen." }
entries[19811] = { ["name"] = "Vernichten" }
entries[19812] = { ["name"] = "Wutanfall", ["text"] = "Sofort\nVerringert die Zeit zwischen Euren Angriffen 8 Sek. lang um 100%." }
entries[19813] = { ["name"] = "Rückschlag", ["text"] = "Sofort\nStößt alle Ziele vor dem Zaubernden zurück." }
entries[19814] = { ["name"] = "Meisterliche Zielattrappe", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilgehäuse , Thoriumröhre , Thoriumapparat (2), Echtsilberbarren , Unverwüstliches Leder (2), Runenstoff (4)\nBenötigt Ingenieurskunst\n(275)\nBenutzen: Lässt eine Zielattrappe auf den Boden fallen, die in der Nähe befindliche Monster dazu bringt, sie anzugreifen. Die Attrappe bleibt bis zu ihrer Zerstörung aktiv, maximal jedoch für 15 Sekunden. (2 Min Abklingzeit)" }
entries[19815] = { ["name"] = "Empfindlicher Arkanitwandler", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nArkanitbarren , Eisenweberseide" }
entries[19816] = { ["name"] = "Feuerball", ["text"] = "90 Mana 40 Meter Reichweite\nWirken in 3 sek.\nFügt einem Gegner Feuerschaden zu." }
entries[19817] = { ["name"] = "Doppelangriff", ["text"] = "Gewährt dem Zaubernden 0 zusätzliche Angriffe.\n(Procchance: 10%, 3s Abklingzeit)" }
entries[19818] = { ["name"] = "Doppelangriff", ["text"] = "Gewährt dem Zaubernden 0 zusätzliche Angriffe.\n(Procchance: 25%, 3s Abklingzeit)" }
entries[19819] = { ["name"] = "Modularer Stimmenverstärker", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEmpfindlicher Arkanitwandler (2), Goldkraftkern , Thoriumapparat , Großer Opal\nModularer Stimmenverstärker\nWird beim Anlegen gebunden\nHals\nAnlegen: Verringert die Wirkungsdauer jeglicher Stille- und Unterbrechungseffekte gegen den Träger um 10%. Dieser Effekt ist nicht mit anderen Effekten dieser Art stapelbar." }
entries[19820] = { ["name"] = "Zerfleischen", ["text"] = "10 Meter Reichweite\nSofort\nVerursacht alle 2 Sek. 300 Schaden bei einem Feind und verringert sein Bewegungstempo um 50%. Hält 20 Sek. lang an." }
entries[19821] = { ["name"] = "Arkane Bombe", ["text"] = "15 Meter Reichweite\nWirken in 1.5 sek." }
entries[19822] = { ["name"] = "Totstellen" }
entries[19823] = { ["name"] = "Feuernova - Bild" }
entries[19825] = { ["name"] = "Schutzbrille des Meisteringenieurs", ["text"] = "Wirken in 50 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nFeuerschutzbrille , Gewaltiger Smaragd (2), Verzaubertes Leder (4)\nSchutzbrille des Meisteringenieurs\nWird beim Anlegen gebunden\nKopf Stoff\n118 Rüstung\n+16 Ausdauer\n+17 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Ingenieurskunst\n(280)" }
entries[19830] = { ["name"] = "Arkanitdrachling", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMechanischer Mithrildrachling , Empfindlicher Arkanitwandler (4)\nArkanitdrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n50\nBenötigt Ingenieurskunst\n(300)\nBenutzen: Aktiviert Euren Arkanitdrachling, damit er 1 Min. lang für Euch kämpft. (5 Min Abklingzeit)" }
entries[19831] = { ["name"] = "Arkane Bombe", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer\nReagenzien:\nEmpfindlicher Arkanitwandler , Thoriumbarren (3), Runenstoff\n(3)\nBenötigt Ingenieurskunst\n(300)" }
entries[19832] = { ["name"] = "Besitz ergreifen", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 1.5 min)\nBeherrscht die Gedanken eines Ziels." }
entries[19833] = { ["name"] = "Fehlerloses Arkanitgewehr", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nArkanitbarren (10), Thoriumröhre (2), Essenz des Feuers (2), Essenz der Erde (2), Azerothischer Diamant (2), Verzaubertes Leder (2)\nFehlerloses Arkanitgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n109 - 204 Schaden Tempo 3.00\n(52.17 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\n56\nAnlegen: Erhöht die kritische Trefferwertung um 9.\nAnlegen: Erhöht die Distanzangriffskraft um 10." }
