entries[19873] = { ["name"] = "Ei zerstören", ["text"] = "10 Meter Reichweite\nWirken in 3 sek. 7 sek. Abklingzeit\nZerstört ein in der Nähe befindliches Ei." }
entries[19874] = { ["name"] = "Blitzschlag", ["text"] = "20 Mana 30 Meter Reichweite\nWirken in 1.6 sek.\nÜberzieht ein Ziel mit 180 to 250 Naturschaden." }
entries[19878] = { ["name"] = "Dämonen aufspüren", ["text"] = "Sofort\nZeigt den Aufenthaltsort aller in der Nähe befindlichen Dämonen auf der Minikarte an." }
entries[19879] = { ["name"] = "Drachkin aufspüren", ["text"] = "Sofort\nZeigt alle in der Nähe befindlichen Drachkin auf der Minikarte an." }
entries[19880] = { ["name"] = "Elementare aufspüren", ["text"] = "Sofort\nZeigt alle in der Nähe befindlichen Elementare auf der Minikarte an." }
entries[19882] = { ["name"] = "Riesen aufspüren", ["text"] = "Sofort\nZeigt alle in der Nähe befindlichen Riesen auf der Minikarte an." }
entries[19883] = { ["name"] = "Humanoide aufspüren", ["text"] = "Sofort\nZeigt alle in der Nähe befindlichen Humanoiden auf der Minikarte an." }
entries[19884] = { ["name"] = "Untote aufspüren", ["text"] = "Sofort\nZeigt alle in der Nähe befindlichen Untoten auf der Minikarte an." }
