entries[19887] = { ["name"] = "Kochfachmann", ["text"] = "100 Meter Reichweite\nWirken in 20 sek.\nLehrt Euch, ein Kochfachmann mit einer maximalen Kochkunst von 300 zu werden." }
entries[19889] = { ["name"] = "Angelexperte", ["text"] = "100 Meter Reichweite\nWirken in 20 sek.\nLehrt Euch, ein Angelexperte mit einer maximalen Angelfertigkeit von 225 zu werden." }
