entries[20066] = { ["name"] = "Buße", ["text"] = "9% von Grundmana 30 Meter Reichweite\nSofort 1 min Abklingzeit\nVersetzt das feindliche Ziel in einen meditativen Zustand und macht es so bis zu 1 Min. lang handlungsunfähig. Jeglicher außer durch 'Tadel' erlittene Schaden wird das Ziel wecken. Kann nur auf Dämonen, Drachkin, Riesen, Humanoide und Untote gewirkt werden." }
