entries[20154] = { ["name"] = "Siegel der Rechtschaffenheit", ["text"] = "14% von Grundmana\nSofort\nErfüllt den Paladin 30 Min. lang mit heiligem Geist, durch den jeder Nahkampfangriff zusätzlich [Mainhand weapon base speed * (0.011 * Attack power + 0.022 * Spell power) * ( 100 ) / 100] Heiligschaden verursacht. [ Glyphe 'Siegel der Wahrheit' : Gewährt zudem, so lang der Effekt aktiv ist, 10 Waffenkunde ] Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein [ Richturteil : Die Entfesselung der Energie dieses Siegels fügt einem Feind (1 + 0.2 * Attack power + 0.32 * Spell power) Heiligschaden zu / .]" }
entries[20164] = { ["name"] = "Siegel der Gerechtigkeit", ["text"] = "14% von Grundmana\nSofort\nErfüllt den Paladin 30 Min. lang mit dem Geist der Gerechtigkeit, durch den Eure Nahkampfangriffe auf Einzelziele 5 Sek. lang das maximale Bewegungstempo des Gegners einschränken und zusätzlich [Mainhand weapon base speed * (0.005 * Attack power + 0.01 * Spell power) * ( 100 ) / 100] Heiligschaden verursachen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Feind (1 + 0.25 * Spell power + 0.16 * Attack power) Heiligschaden zu." }
entries[20165] = { ["name"] = "Siegel der Einsicht", ["text"] = "14% von Grundmana\nSofort\nErfüllt den Paladin 30 Min. lang mit göttlicher Kraft, die jedem gegen nur ein Ziel gerichteten Nahkampfangriff eine Chance verleiht, den Paladin um (0.15 * Attack power + 0.15 * Spell power) zu heilen und 4% seines Grundmanas wiederherzustellen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Feind (1 + 0.25 * Spell power + 0.16 * Attack power) Heiligschaden zu." }
entries[20167] = { ["name"] = "Siegel der Einsicht", ["text"] = "Sofort\nErfüllt den Paladin bis Abbruch lang mit göttlicher Kraft, die jedem gegen nur ein Ziel gerichteten Nahkampfangriff eine Chance verleiht, den Paladin um (0.15 * Attack power + 0.15 * Spell power) zu heilen und 0% seines Grundmanas wiederherzustellen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Feind (1 + 0.25 * Spell power + 0.16 * Attack power) Heiligschaden zu." }
entries[20170] = { ["name"] = "Siegel der Gerechtigkeit", ["text"] = "100 Meter Reichweite\nSofort\nErfüllt den Paladin 30 Min. lang mit dem Geist der Gerechtigkeit, der bei jedem gegen nur ein Ziel gerichteten Nahkampfangriff 5 Sek. lang das maximale Bewegungstempo des Gegners einschränkt und zusätzlichen Heiligschaden verursacht. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels verursacht bei einem Feind (1 + 0.25 * Spell power + 0.16 * Attack power) Heiligschaden." }
